def keep_each_versions_add_on_rules(apps, schema_editor):
    """Every existing version keeps the rule it was published with: any
    add-on went with any main service or maintenance plan (decision 0106).
    Published versions never change, so the rows are written here, below
    the model's lock. The new rules come with the next version, loaded by
    load_pricebook from data/services.yaml."""
    Service = apps.get_model("pricebook", "Service")
    PricebookVersion = apps.get_model("pricebook", "PricebookVersion")
    AddOnFit = apps.get_model("pricebook", "AddOnFit")
    add_ons = list(Service.objects.filter(kind="add_on"))
    services = list(Service.objects.filter(kind__in=["main", "maintenance_plan"]))
    for version in PricebookVersion.objects.all():
        for add_on in add_ons:
            for service in services:
                AddOnFit.objects.get_or_create(version=version, add_on=add_on, service=service)


